function bmRiskRows(family) {
  if (family === 'employer') {
    return [
      { category: 'Critical', issues: 'Labour Agreement currency, employer coverage, occupation coverage, nomination consistency, lawful concession basis, salary/AMSR position and evidence sufficiency.', position: 'The matter should not be lodged until these issues are resolved.', response: 'Obtain original agreement, nomination and salary evidence; prepare a criterion-by-criterion evidence matrix.' },
      { category: 'High', issues: 'English, skills, registration, identity, lawful status, character, PIC 4020, prior refusals/cancellations and family-member issues.', position: 'These issues can defeat an otherwise supportable pathway.', response: 'Verify before filing and request further documents where gaps exist.' },
      { category: 'Managed', issues: 'Occupation and duties alignment, employment history chronology, business need, translations, certification and final evidence indexing.', position: 'Manageable if documents are consistent and complete.', response: 'Control through evidence review and final agent checklist.' },
      { category: 'Standard preparation', issues: 'Final document organisation, evidence indexing, Departmental record checks and final migration-agent review.', position: 'Required for professional file control.', response: 'Complete before final lodgement advice.' }
    ];
  }
  return [
    { category: 'Critical', issues: 'Any validity bar, missing threshold requirement, unavailable pathway or evidence defect that prevents a safe lodgement recommendation.', position: 'The matter should not be lodged until any threshold defect is resolved.', response: 'Resolve before any lodgement recommendation.' },
    { category: 'High', issues: 'Applicant eligibility, identity, immigration history, public-interest, document-integrity and evidence sufficiency issues.', position: 'These issues may materially affect prospects or strategy.', response: 'Verify before filing.' },
    { category: 'Managed', issues: 'Document organisation, translations, timing, consistency checks and final evidence indexing.', position: 'Manageable through careful preparation.', response: 'Control through evidence review.' }
  ];
}

function bmWriteRiskPriorityTable(doc, family) {
  const rows = bmRiskRows(family);
  const widths = [82, 150, 125, 138];
  const headers = ['Risk level', 'Issues', 'Professional position', 'Required response'];
  bmWriteCompactTable(doc, headers, rows.map(r => [r.category, r.issues, r.position || r.response, r.response]), widths);
}

function bmWriteCompactTable(doc, headers, rows, widths) {
  const x0 = PAGE.L;
  const tableW = widths.reduce((a, b) => a + b, 0);
  const pad = 6;
  const lineGap = 1.8;
  const headH = 24;
  ensureSpace(doc, headH + 20);
  let y = doc.y;
  doc.rect(x0, y, tableW, headH).fillAndStroke(BRAND.navy, BRAND.navy);
  let x = x0;
  headers.forEach((h, i) => {
    doc.font('Helvetica-Bold').fontSize(7.6).fillColor('#ffffff').text(cleanText(h), x + pad, y + 7, { width: widths[i] - pad * 2, lineGap });
    x += widths[i];
  });
  doc.y = y + headH;
  for (const row of rows) {
    const cells = row.map(v => cleanText(v));
    const heights = cells.map((c, i) => doc.font(i === 0 ? 'Helvetica-Bold' : 'Helvetica').fontSize(i === 0 ? 7.9 : 7.4).heightOfString(c, { width: widths[i] - pad * 2, lineGap }));
    const h = Math.max(38, Math.max(...heights) + 14);
    ensureSpace(doc, h + 8);
    y = doc.y;
    doc.rect(x0, y, tableW, h).fillAndStroke('#ffffff', BRAND.line);
    x = x0;
    cells.forEach((c, i) => {
      if (i > 0) doc.moveTo(x, y).lineTo(x, y + h).strokeColor(BRAND.line).lineWidth(0.4).stroke();
      doc.font(i === 0 ? 'Helvetica-Bold' : 'Helvetica').fontSize(i === 0 ? 7.9 : 7.4).fillColor(i === 0 ? BRAND.navy : BRAND.text).text(c, x + pad, y + 7, { width: widths[i] - pad * 2, lineGap });
      x += widths[i];
    });
    doc.y = y + h;
  }
  doc.moveDown(0.85);
  doc.x = PAGE.L;
}

function bmNormaliseAppendixRisk(row) {
  const text = cleanText(`${row.area || ''} ${row.issue || ''} ${row.position || ''} ${row.action || ''}`).toLowerCase();

  // Critical is reserved for true threshold blockers. Do not escalate ordinary
  // verification issues merely because the action says “verify”, “review”, or “required”.
  if (/schedule 1|valid application requirements|all schedule 1 validity/.test(text)) return 'Critical';
  if (/nomination can support.*decision|valid employer nomination exists|nomination.*through to decision/.test(text)) return 'Critical';
  if (/executed labour agreement.*(current|applies)|labour agreement.*current.*applies|occupation.*expressly covered by.*labour agreement|nomination.*exact labour agreement terms|reconcile.*labour agreement terms/.test(text)) return 'Critical';
  if (/salary.*amsr.*labour agreement|amsr.*salary.*labour agreement|salary.*concession/.test(text)) return 'Critical';
  if (/evidence sufficiency|lodgement readiness/.test(text)) return 'Critical';

  if (/identity|biographical|lawful status|visa status|current location|full-time position|genuine nominated position|position not created|employment contract|concession|age requirement|english|skills|qualification|registration|licens|character|pic 4020|4020|special return|prior refusal|cancellation|family member|secondary applicant|police|court|health|work-rights|employment compliance|market salary|guaranteed earnings|employment terms|consistency|document integrity/.test(text)) return 'High';
  return 'Managed';
}

function bmShortAppendixPosition(row) {
  const risk = bmNormaliseAppendixRisk(row);
  if (risk === 'Critical') return 'Resolve before any lodgement recommendation.';
  if (risk === 'High') return 'Verify before filing.';
  return 'Manage through evidence review.';
}

function bmDeduplicateAppendixRows(rows) {
  const riskRank = { Critical: 4, High: 3, Managed: 2, 'Standard preparation': 1 };
  const canonicalKey = row => {
    const text = `${row.area || ''} ${row.issue || ''}`.toLowerCase();
    if (/english/.test(text)) return 'applicant::english';
    if (/skill|qualification|experience/.test(text)) return 'applicant::skills-qualifications-experience';
    if (/salary|amsr|guaranteed earnings|market salary/.test(text)) return 'salary::salary-amsr';
    if (/employment terms|contract|nes|award|enterprise/.test(text)) return 'salary::employment-terms';
    if (/labou?r agreement.*current|executed labou?r agreement|agreement.*applies/.test(text)) return 'labour-agreement::currency-coverage';
    if (/occupation.*covered|occupation coverage/.test(text)) return 'labour-agreement::occupation-coverage';
    if (/concession/.test(text)) return `${row.area || 'criteria'}::concessions`;
    if (/nomination.*support|valid employer nomination|nomination exists/.test(text)) return 'nomination::valid-supporting-nomination';
    if (/identity|biographical/.test(text)) return 'applicant::identity';
    if (/health/.test(text)) return 'public-interest::health';
    if (/character|police|court/.test(text)) return 'public-interest::character';
    if (/pic 4020|integrity|false|misleading/.test(text)) return 'public-interest::integrity';
    return `${cleanText(row.area).toLowerCase()}::${cleanText(row.issue).toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 80)}`;
  };
  const merged = new Map();
  for (const row of ensureArray(rows)) {
    const key = canonicalKey(row);
    const existing = merged.get(key);
    if (!existing) {
      merged.set(key, { ...row });
      continue;
    }
    const existingRank = riskRank[existing.risk] || 0;
    const newRank = riskRank[row.risk] || 0;
    if (newRank > existingRank) {
      existing.risk = row.risk;
      existing.position = row.position;
    }
    const action = cleanText(row.action);
    if (action && !cleanText(existing.action).toLowerCase().includes(action.toLowerCase())) {
      existing.action = `${cleanText(existing.action)} ${action}`.trim();
    }
  }
  return [...merged.values()].map(row => {
    row.risk = bmNormaliseAppendixRisk(row);
    row.position = bmShortAppendixPosition(row);
    return row;
  });
}


function bmAppendixAreaLabel(section, issue) {
  const text = cleanText(`${section || ''} ${issue || ''}`).toLowerCase();
  if (/valid|schedule 1|application method|visa application charge|stream|pathway|time-of-application|time of application|time-of-decision|time of decision/.test(text)) return 'Validity';
  if (/labou?r agreement|dama|agreement terms|agreement ceiling|ceiling|location limit|occupation list|concession schedule/.test(text)) return 'Labour Agreement';
  if (/nomination|nominating employer|employer|sponsor|business|genuine position|full-time|full time|created primarily|operational|adverse information/.test(text)) return 'Nomination';
  if (/salary|amsr|market salary|guaranteed earnings|employment contract|employment terms|nes|award|enterprise agreement|income/.test(text)) return 'Salary';
  if (/identity|biographical|age|english|skills|qualification|experience|registration|licens|applicant work|work-rights|work rights|employment history|lawful status|visa status|current location/.test(text)) return 'Applicant';
  if (/health|character|police|court|pic 4020|4020|integrity|false|misleading|special return|src|refusal|cancellation|compliance|debt|removal|deportation|exclusion/.test(text)) return 'Public interest';
  if (/family|secondary|dependent|partner|child|relationship/.test(text)) return 'Family';
  if (/translation|certification|document quality|evidence sufficiency|lodgement readiness|final migration-agent review|final agent review|consistency across forms|file control|evidence index/.test(text)) return 'File control';
  return 'Criteria';
}

function bmAppendixRows(criteria) {
  const rows = ensureArray(criteria).filter(Boolean).map(item => {
    const issue = sentenceCase(clientFriendlyCriterionLabel(item.criterion || 'Grant criterion'));
    const row = {
      area: bmAppendixAreaLabel(item.pdfSection || inferGrantCriteriaSection(item.criterion, '', ''), issue),
      issue,
      risk: v12RiskLabel(item),
      position: v12CompactPosition(item),
      action: v12CompactAction(item)
    };
    row.risk = bmNormaliseAppendixRisk(row);
    row.position = bmShortAppendixPosition(row);
    return row;
  });
  return bmDeduplicateAppendixRows(rows);
}

function bmWriteAppendixSchedule(doc, criteria) {
  const rows = bmAppendixRows(criteria);
  if (!rows.length) return;
  addPage(doc, 'Appendix A — full lodgement-readiness matrix');
  writeTitle(doc, 'Appendix A — Full lodgement-readiness matrix', { gold: true });
  writePara(doc, 'This appendix is a professional lodgement-readiness schedule. It records the issue, risk level, assessment position and required action for file control. It is not a guarantee that each criterion is satisfied.', { size: 9.2 });

  // Permanent Appendix layout: group criteria by proper legal category and render
  // full-width schedule cards. This avoids false "Nomination" labels for public
  // interest/family rows and prevents any table-column overflow or ellipsis.
  const groupOrder = ['Validity', 'Nomination', 'Labour Agreement', 'Applicant', 'Salary', 'Public interest', 'Family', 'File control', 'Criteria'];
  const grouped = new Map();
  for (const row of rows) {
    const area = cleanText(row.area, 'File control');
    if (!grouped.has(area)) grouped.set(area, []);
    grouped.get(area).push(row);
  }
  const orderedAreas = groupOrder.filter(a => grouped.has(a)).concat([...grouped.keys()].filter(a => !groupOrder.includes(a)));

  const pad = 12;
  const badgeW = 86;
  const gap = 9;
  const innerW = PAGE.WIDTH - (pad * 2);
  const titleW = innerW - badgeW - gap;

  for (const area of orderedAreas) {
    const groupRows = grouped.get(area) || [];
    if (!groupRows.length) continue;

    ensureSpace(doc, 42);
    const groupY = doc.y;
    doc.roundedRect(PAGE.L, groupY, PAGE.WIDTH, 25, 7).fillAndStroke('#f8fafc', '#d8e0ea');
    doc.font('Helvetica-Bold').fontSize(10.2).fillColor(BRAND.navy)
      .text(area, PAGE.L + 12, groupY + 7, { width: PAGE.WIDTH - 24 });
    doc.y = groupY + 34;
    doc.x = PAGE.L;

    for (const row of groupRows) {
      const issue = cleanText(row.issue, 'Criterion requiring verification');
      const risk = cleanText(row.risk, 'Managed');
      const position = cleanText(row.position, 'Manage through evidence review.');
      const action = cleanText(row.action, 'Verify this criterion against original documents before lodgement.');
      const colour = riskColour(risk);

      // Area is already shown as a group heading, so card title is not repeated
      // as "Nomination — ..." on every item.
      const title = issue;
      const positionText = `Position: ${position}`;
      const actionText = `Required action: ${action}`;

      doc.font('Helvetica-Bold').fontSize(9.2);
      const titleH = doc.heightOfString(title, { width: titleW, lineGap: 1.45 });
      doc.font('Helvetica').fontSize(8.7);
      const positionH = doc.heightOfString(positionText, { width: innerW, lineGap: 1.7 });
      const actionH = doc.heightOfString(actionText, { width: innerW, lineGap: 1.7 });
      const cardH = Math.max(82, titleH + positionH + actionH + 48);

      ensureSpace(doc, cardH + 9);
      const y = doc.y;

      doc.roundedRect(PAGE.L, y, PAGE.WIDTH, cardH, 8).fillAndStroke('#ffffff', '#d8e0ea');

      doc.font('Helvetica-Bold').fontSize(9.2).fillColor(BRAND.navy)
        .text(title, PAGE.L + pad, y + 11, { width: titleW, lineGap: 1.45 });

      const badgeY = y + 10;
      doc.roundedRect(PAGE.R - badgeW - pad, badgeY, badgeW, 19, 9)
        .fillAndStroke(colour.bg, colour.border);
      doc.font('Helvetica-Bold').fontSize(7.4).fillColor(colour.text)
        .text(risk.toUpperCase(), PAGE.R - badgeW - pad + 6, badgeY + 5.4, { width: badgeW - 12, align: 'center', lineBreak: false });

      let cursorY = y + 17 + Math.max(titleH, 19);
      doc.font('Helvetica-Bold').fontSize(8.45).fillColor(BRAND.muted)
        .text('Position:', PAGE.L + pad, cursorY, { width: 58, lineBreak: false });
      doc.font('Helvetica').fontSize(8.65).fillColor(BRAND.text)
        .text(position, PAGE.L + pad + 62, cursorY, { width: innerW - 62, lineGap: 1.7 });

      cursorY += positionH + 7;
      doc.font('Helvetica-Bold').fontSize(8.45).fillColor(BRAND.muted)
        .text('Required action:', PAGE.L + pad, cursorY, { width: 82, lineBreak: false });
      doc.font('Helvetica').fontSize(8.65).fillColor(BRAND.text)
        .text(action, PAGE.L + pad + 86, cursorY, { width: innerW - 86, lineGap: 1.7 });

      doc.y = y + cardH + 8;
      doc.x = PAGE.L;
    }
  }
}

function bmPrimaryIssueList(subclass, stream, family) {
  if (bmAgreementMatter(subclass, stream)) {
    return [
      'whether the executed Labour Agreement is current and applies to the nominating employer',
      'whether the nominated occupation is expressly covered by the Labour Agreement',
      'whether the nomination is consistent with the exact agreement terms, limits, location requirements, concessions and special conditions',
      'whether the salary, AMSR and employment terms are supported by objective employer records',
      'whether the applicant satisfies, or lawfully falls within a concession for, the relevant age, English, skills, qualifications and registration requirements',
      'whether health, character, visa-history, document-integrity and family-member issues are clear or manageable'
    ];
  }
  return [
    'whether the selected subclass and stream are legally available on the information provided',
    'whether each threshold criterion can be verified against original documents',
    'whether any health, character, immigration-history or document-integrity issue affects lodgement strategy',
    'whether the evidence is sufficient to support a final professional recommendation'
  ];
}

function bmWriteLabourAgreementIssues(doc, subclass, stream) {
  writeTitle(doc, '4. Key Labour Agreement issues requiring verification', { gold: true });
  writeSubheading(doc, '4.1 Labour Agreement currency and coverage');
  writePara(doc, 'The first issue is whether the executed Labour Agreement is current and applies to the nominating employer and proposed role. Before lodgement, Bircan Migration should obtain and review the executed Labour Agreement, including any schedules, occupation lists, concessions, location limits, ceilings, special conditions and DAMA material where relevant.', { size: 9.7 });
  bmWriteBulletList(doc, ['the agreement is currently in force', 'the employer is a party to or properly covered by the agreement', 'the agreement permits a Subclass 186 nomination', 'the nominated occupation is included', 'the proposed work location is permitted', 'any applicable cap, ceiling or quota has not been exceeded', 'any concession relied upon is expressly available']);
  writePara(doc, 'If the agreement does not support the employer, role, location, occupation or concession relied upon, the application strategy must be revised before filing.', { size: 9.7 });

  writeSubheading(doc, '4.2 Occupation coverage');
  writePara(doc, 'The nominated occupation must be expressly covered by the Labour Agreement. It is not sufficient that the applicant has skills or experience in the role. The nomination must be legally supportable under the exact terms of the agreement.', { size: 9.7 });
  bmWriteBulletList(doc, ['the Labour Agreement occupation schedule', 'any DAMA occupation list where relevant', 'any location-specific restrictions', 'any occupation-specific concession rules', 'the actual duties performed or proposed', 'the position description and employer business need']);
  writePara(doc, 'A duties and occupation matrix should be prepared to show that the actual role aligns with the nominated occupation and the agreement coverage.', { size: 9.7 });

  writeSubheading(doc, '4.3 Nomination consistency');
  writePara(doc, 'The nomination must be reconciled against the exact Labour Agreement terms. This means the nomination should be checked against occupation, location, salary, guaranteed earnings, concessions, employment conditions, full-time and ongoing position requirements, business need, agreement limits and special conditions.', { size: 9.7 });
  writePara(doc, 'If the nomination is inconsistent with the Labour Agreement, the visa application may be exposed to refusal even if the applicant otherwise appears suitable.', { size: 9.7 });

  writeSubheading(doc, '4.4 Salary, AMSR and employment conditions');
  writePara(doc, 'The salary and employment terms must be supported by objective evidence. Bircan Migration should review the signed employment contract, guaranteed earnings, market salary or AMSR evidence, payroll records where available, tax and superannuation records where relevant, award or enterprise agreement coverage, Labour Agreement salary concessions and evidence that the proposed terms are lawful and consistent with the nomination.', { size: 9.7 });
  writePara(doc, 'If a salary concession is relied upon, the agreement must expressly permit that concession for this occupation and applicant. The concession should not be assumed.', { size: 9.7 });

  writeSubheading(doc, '4.5 Concessions');
  writePara(doc, 'Labour Agreement matters often involve concessions. However, a concession should only be relied upon if it is expressly permitted and properly evidenced. Each concession should be identified, legally mapped and supported by documentary evidence before final lodgement advice is issued.', { size: 9.7 });
  bmWriteBulletList(doc, ['age concession', 'English concession', 'skills or qualification concession', 'salary concession', 'location or occupation-specific concession', 'any DAMA-specific concession', 'any special condition attached to the agreement']);

  writeSubheading(doc, '4.6 English, skills, qualifications and registration');
  writePara(doc, 'The applicant’s English, skills, qualifications, experience and registration position must be verified before lodgement. This includes English test results or passport exemption evidence, any lawful Labour Agreement English concession, qualifications, employment references, skills evidence, registration or licensing evidence, occupation-specific requirements and proof that any concession relied upon applies to the applicant.', { size: 9.7 });
}

function bmWriteExecutiveProfessionalAdvice(doc, meta) {
  const { applicantName, pathwayLabel, subclass, stream, family } = meta;
  writeTitle(doc, '1. Executive professional advice', { gold: true });
  writePara(doc, `Dear ${applicantName && applicantName !== 'Client' ? applicantName : 'Client'},`, { size: 10.2 });
  writePara(doc, `I have reviewed the information presently available for a proposed ${pathwayLabel} visa pathway.`, { size: 9.8 });
  writePara(doc, bmAgreementMatter(subclass, stream)
    ? 'My professional opinion is that the pathway may be available in principle, but the matter is not presently lodgement-ready. I do not recommend immediate lodgement. The application should only progress after the executed Labour Agreement, employer nomination, occupation coverage, concession basis, salary and AMSR evidence, and applicant eligibility evidence have been verified against original documents.'
    : 'My professional opinion is that the pathway may be available in principle, but the matter is not presently lodgement-ready. I do not recommend immediate lodgement until the selected pathway, threshold requirements, applicant evidence, public-interest criteria and any sponsor, nomination, invitation or relationship requirement have been verified against original documents.', { size: 9.8 });
  writePara(doc, bmAgreementMatter(subclass, stream)
    ? 'The Labour Agreement Stream is evidence-controlled. The Department will not assess the matter only on the basis that the employer wishes to nominate or that the applicant wishes to proceed. The application must be supported by a valid nomination that is consistent with the exact terms of the Labour Agreement. Any age, English, skills, salary, location or occupation concession must be expressly available under that agreement and supported by evidence.'
    : 'The application must be supported by evidence that is internally consistent and legally aligned with the selected subclass and stream. The correct next step is evidence verification, not immediate filing.', { size: 9.8 });
  bmWriteCompactTable(doc, ['Client question', 'Professional answer'], [
    ['Is this pathway open?', bmAgreementMatter(subclass, stream) ? 'Potentially, subject to verification of the Labour Agreement, nomination, occupation coverage, concessions, salary/AMSR and applicant evidence.' : 'Potentially, subject to verification of the pathway, applicant evidence and public-interest position.'],
    ['Should the application be lodged now?', 'No. Lodgement is not recommended on the current evidence position.'],
    ['What should happen next?', 'Proceed to a formal evidence review and lodgement-readiness assessment before filing.'],
    ['What is the main risk?', bmAgreementMatter(subclass, stream) ? 'The matter may fail if the Labour Agreement or nomination does not support the employer, role, occupation, location, salary or concession relied upon.' : 'The matter may fail if the selected pathway and evidence do not support the same legal position.']
  ], [145, 350]);
  writePara(doc, 'This recommendation protects the client from avoidable refusal risk, unnecessary cost and a weaker future migration position. It also ensures that any final lodgement advice is based on verified evidence rather than assumptions.', { size: 9.8 });
}

